use namespace workers;
declare actor Foo;
mtd (Foo self) receive(ActorMail<String> mail): void {
  self.send(41);
  self.end();
}

declare actor Foo;
mtd (Foo mut self.state.counter) increment(): void {
  self.handle_state(critical-write |s| -> { s.counter += 1; });
}

declare actor Foo;
mtd (Foo mut self.state.{counter, xyz}) update(): void {
  self.handle_state(critical-write |s| -> { s.counter += 1; s.xyz = 2; });
}

declare actor Foo;
mtd (Foo mut self.state.counter) update(): void {
 self.handle_state(critical-write |s| -> { s.xyz = 2; });
}

declare actor Foo;
mtd (Foo self) update(): void {
 self.handle_state(critical-write |s| -> { s.counter = 2; });
}

declare actor Foo;
define state on actor Foo as { let int counter: 0; }
mtd (Foo mut self.state.xyz) update(): void {
 self.handle_state(critical-write |s| -> { s.xyz = 2; });
}

declare actor Foo;
define state on actor Foo as { let int counter: 0; let int xyz: 0; }
mtd (Foo mut self.state.counter) update(): void {
 self.handle_state(critical-write |s| -> { unknown_effect(s.counter); });
}

declare actor Foo;
define state on actor Foo as { let int counter: 0; }
mtd (Foo mut self.state.counter) update(): void {
 self.handle_state(critical-write |s| -> { await tick(); s.counter += 1; });
}

declare actor Foo;
define state on actor Foo as { let int counter: 0; let int xyz: 0; }
mtd (Foo mut self.state.counter) inc(): void {
 self.handle_state(critical-write |s| -> { s.counter += 1; });
}
mtd (Foo mut self.state.xyz) bump(): void {
 self.handle_state(critical-write |s| -> { s.xyz += 1; });
}
